create or replace package body t003_fees as
  c_rate    constant number := 0.01;
  c_min_fee constant number := 1;
  c_max_fee constant number := 10;

  function fee_for(p_amount in number) return number is
  begin
    -- The original logic was: greatest(least(round(p_amount * c_rate, 2), c_min_fee), c_max_fee);
    -- This incorrectly caps the fee at c_min_fee if p_amount * c_rate is less than c_min_fee,
    -- and then applies c_max_fee if it exceeds c_max_fee.
    -- The requirement is: 1% of the amount, at least 1.00 and at most 10.00.
    -- This means: MAX(MIN(p_amount * c_rate, c_max_fee), c_min_fee)
    return greatest(least(round(p_amount * c_rate, 2), c_max_fee), c_min_fee);
  end fee_for;
end t003_fees;
